   if($act==='approve'&&$l['status']==='menunggu'){$pdo->prepare("UPDATE loans SET status='disetujui',approved_by=?,approver_note=? WHERE id=?")->execute([user()['id'],'Disetujui melalui sistem',$id]);}
   if($act==='reject'&&$l['status']==='menunggu'){$pdo->prepare("UPDATE loans SET status='ditolak',approved_by=? WHERE id=?")->execute([user()['id'],$id]);$pdo->prepare("UPDATE assets SET availability='tersedia' WHERE id=?")->execute([$l['asset_id']]);}
   if($act==='checkout'&&$l['status']==='disetujui'){$pdo->prepare("UPDATE loans SET status='dipinjam',checkout_at=NOW(),checkout_condition='Baik dan lengkap' WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE assets SET availability='dipinjam' WHERE id=?")->execute([$l['asset_id']]);}
   if($act==='return'&&in_array($l['status'],['dipinjam','terlambat'])){$pdo->prepare("UPDATE loans SET status='dikembalikan',returned_at=NOW(),return_condition='Baik dan lengkap' WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE assets SET availability='tersedia' WHERE id=?")->execute([$l['asset_id']]);}
   $pdo->prepare('INSERT INTO audit_logs(user_id,action,details) VALUES(?,?,?)')->execute([user()['id'],$act,'Peminjaman #'.$id]);
  }$pdo->commit();flash('Status transaksi berhasil diperbarui.');$back=in_array($_POST['back']??'', ['approval','handover'], true)?$_POST['back']:'approval';$backType=in_array($_POST['loan_type']??'', ['sementara','jangka_panjang'],true)?$_POST['loan_type']:'sementara';header('Location:index.php?page='.$back.'&type='.urlencode($backType));exit;
 }
}
$pdo->exec("UPDATE loans SET status='terlambat' WHERE status='dipinjam' AND due_date<CURDATE()");
